+open Js_of_ocaml;
+open Haz3lcore;
+open Util;
+open Virtual_dom.Vdom;
+
+/* Offside staggering, top-down greedy: an offside display spanning K rows
+   (a card fan, a tall rich view) must clear (a) the end of every code line
+   it spans — not just its own — and (b) any overlapping display owned by
+   rows above. Rows above have priority; displays below re-solve against
+   the result. A single pass terminates because displays only ever move
+   right.
+
+   Runs in after_display (precedent: RefractorShift/ScrollWidth): widths
+   and heights come from the rendered DOM and positions are patched
+   imperatively before paint. The pass is solved PER code container, each
+   against its own line ends — CodeWithStatics writes them onto the
+   container as `data-row-ends` (via `row_ends_attr`) from that editor's
+   Measured, so multi-cell views (exercises, derivations, instructor
+   tutorials) never read another cell's rows or collide across cells. The
+   base render position (ProjectorView.offside_base) is reproduced as the
+   single-row floor, so nothing moves unless staggering demands it. */
+
+/* keep in sync with ProjectorView.offside_offset / stack_gap */
+let offside_offset = 4;
+let stack_gap = 2;
+
+let row_ends_attr_name = "data-row-ends";
+
+/* Dense per-row line ends ("max_col,max_col,..." indexed by row; absent
+   rows read as 0), attached to a code container for `update`. */
+let row_ends_attr = (measured: Measured.t): Attr.t => {
+  let rows = measured.rows;
+  let n =
+    switch (IntMap.max_binding_opt(rows)) {
+    | Some((r, _)) => r + 1
+    | None => 0
+    };
+  List.init(n, r =>
+    switch (IntMap.find_opt(r, rows)) {
+    | Some(row) => string_of_int(Measured.Rows.(row.max_col))
+    | None => "0"
+    }
+  )
+  |> String.concat(",")
+  |> Attr.create(row_ends_attr_name);
+};
+
+let row_ends_of_container = (el: Js.t(Dom_html.element)): array(int) =>
+  Js.Opt.case(
+    el##getAttribute(Js.string(row_ends_attr_name)),
+    () => [||],
+    s =>
+      Js.to_string(s)
+      |> String.split_on_char(',')
+      |> List.map(s => Option.value(int_of_string_opt(s), ~default=0))
+      |> Array.of_list,
+  );
+
+type item = {
+  row: int,
+  origin_col: int,
+  el: Js.t(Dom_html.element),
+  w_px: float,
+  h_px: float,
+};
+
+let items_of_container = (container: Js.t(Dom_html.element)): list(item) => {
+  let nodes = container##querySelectorAll(Js.string(".offside-wrapper"));
+  let items = ref([]);
+  for (i in 0 to nodes##.length - 1) {
+    switch (Js.Opt.to_option(nodes##item(i))) {
+    | Some(el) =>
+      let attr = (a: string): option(int) =>
+        Js.Opt.case(
+          el##getAttribute(Js.string(a)),
